	// Method 1: Using RDVL to get Vector Length in bytes, then divide by 4
	rdvl x28, #1             // x28 = Current Vector Length (VL) in bytes. Immediate is multiplier (1 here).
	lsr x28, x28, #2         // x28 = VL / 4 (number of 32-bit S elements)
