	// The innermost loop over y2 is vectorized using SVE.

	mov	w20, #0              // Initialize x1 = 0 (using w20 for x1)
.L_x1_loop:                      // Start loop for x1
	mul	w9, w20, w20         // w9 = x1_sq = x1 * x1

	mov	w21, #0              // Initialize y1 = 0 (using w21 for y1)
.L_y1_loop:                      // Start loop for y1
	// Check if P = (x1, y1) is the origin O(0,0). If so, skip.
	orr w8, w20, w21        // w8 = x1 | y1. w8 is zero only if both x1 and y1 are zero.
	cbz w8, .L_skip_y1_inc  // If w8 is zero (P=O), skip to the y1 increment.

	// Calculate values related to P=(x1, y1)
	mul	w10, w21, w21      // w10 = y1_sq = y1 * y1
	add	w11, w9, w10       // w11 = op2 = x1^2 + y1^2 (squared length of OP)
	dup	z5.s, w11          // Broadcast op2 into SVE register z5 (all lanes = op2)
	dup	z6.s, w21          // Broadcast y1 into SVE register z6 (all lanes = y1)

	mov	w22, #0              // Initialize x2 = 0 (using w22 for x2)
.L_x2_loop:                      // Start loop for x2
	// Calculate values related to Q=(x2, y2) that depend only on x2
	mul	w12, w22, w22      // w12 = x2_sq = x2 * x2
	dup	z7.s, w12          // Broadcast x2_sq into SVE register z7

	sub	w13, w20, w22      // w13 = x1 - x2
	mul	w14, w13, w13      // w14 = x1mx2_sq = (x1 - x2)^2
	dup z8.s, w14          // Broadcast x1mx2_sq into SVE register z8

	// --- SVE Vectorized loop for y2 from 0 to 50 ---
	mov	x23, #0              // x23 = y2_idx = 0 (start index for the y2 vector)
	mov	x24, #51             // x24 = y2_limit = 51 (Loop condition y2 < 51)

.L_y2_loop_sve:                  // Start of the SVE loop over y2
	// Create predicate p0 for active lanes where y2_idx < y2_limit
	// This predicate governs the execution of subsequent SVE instructions marked with /m or /z
	whilelt p0.s, x23, x24     // Set p0 true where element index < limit (x24-x23)

	// If predicate p0 is all false, all y2 values processed; exit the SVE loop
	b.none .L_y2_loop_sve_end // Branch if No Element of p0 is true

	// Generate y2 values for active lanes: [y2_idx, y2_idx+1, ...]
	index z0.s, w23, w15       // Generate indices start=w23, step=w15(1)

	// Calculate squared lengths of OQ and PQ using SVE vectors
	// Use MOVPRFX + destructive op pattern to implement constructive ops with /M predication

	// z1 = y2 * y2
	movprfx z1.s, p0/m, z0.s   // Prepare z1 = z0 for active lanes
	mul     z1.s, p0/m, z1.s, z0.s   // z1 = z1 * z0 (effectively z1 = z0 * z0)

	// z2 = oq2 = x2^2 + y2^2
	movprfx z2.s, p0/m, z7.s   // Prepare z2 = z7 for active lanes
	add     z2.s, p0/m, z2.s, z1.s   // z2 = z2 + z1 (effectively z2 = z7 + z1)

	// z3 = y1 - y2
	movprfx z3.s, p0/m, z6.s   // Prepare z3 = z6 for active lanes
	sub     z3.s, p0/m, z3.s, z0.s   // z3 = z3 - z0 (effectively z3 = z6 - z0)

	// z1 = (y1 - y2)^2 (reuse z1)
	movprfx z1.s, p0/m, z3.s   // Prepare z1 = z3 for active lanes
	mul     z1.s, p0/m, z1.s, z3.s   // z1 = z1 * z3 (effectively z1 = z3 * z3)

	// z4 = pq2 = (x1 - x2)^2 + (y1 - y2)^2
	movprfx z4.s, p0/m, z8.s   // Prepare z4 = z8 for active lanes
	add     z4.s, p0/m, z4.s, z1.s   // z4 = z4 + z1 (effectively z4 = z8 + z1)

	// Check right angle conditions using SVE vector comparisons (zeroing predication /z)
	// p1 = (op2 + oq2 == pq2) -- Check angle at O, result in p1
	movprfx z3.s, p0/m, z5.s   // Prepare z3 = z5 for active lanes
	add     z3.s, p0/m, z3.s, z2.s   // z3 = z3 + z2 (effectively z3 = z5 + z2)
	cmpeq	p1.s, p0/z, z3.s, z4.s // Compare z3 (op2+oq2) and z4 (pq2)

	// p2 = (op2 + pq2 == oq2) -- Check angle at P, result in p2
	movprfx z3.s, p0/m, z5.s   // Prepare z3 = z5 for active lanes
	add     z3.s, p0/m, z3.s, z4.s   // z3 = z3 + z4 (effectively z3 = z5 + z4)
	cmpeq	p2.s, p0/z, z3.s, z2.s // Compare z3 (op2+pq2) and z2 (oq2)

	// p3 = (oq2 + pq2 == op2) -- Check angle at Q, result in p3
	movprfx z3.s, p0/m, z2.s   // Prepare z3 = z2 for active lanes
	add     z3.s, p0/m, z3.s, z4.s   // z3 = z3 + z4 (effectively z3 = z2 + z4)
	cmpeq	p3.s, p0/z, z3.s, z5.s // Compare z3 (oq2+pq2) and z5 (op2)

	// Combine angle predicates: p1 = p1 OR p2 OR p3 (Is there any right angle?)
	// Using /z (zeroing) is fine as subsequent BIC operations also use /z.
	orr	p1.b, p0/z, p1.b, p2.b // p1 = p1 OR p2 (Operate on bytes, zeroing)
	orr	p1.b, p0/z, p1.b, p3.b // p1 = p1 OR p3 (p1 now true if any angle is right)

	// Apply filters to predicate p1: remove invalid triangles
	// Filter 1: Remove cases where Q = O (Origin). This happens if x2=0 and y2=0.
	cmp w22, #0                // Check scalar x2 == 0
	b.ne .L_q_not_o_easy       // If x2 != 0, Q cannot be O, skip this filter step
	// If x2 == 0: Check vector y2 == 0
	cmpeq p2.s, p0/z, z0.s, #0 // p2 = predicate where y2 == 0 (zeroing)
	// Remove lanes from p1 where Q=O condition is met (p1 = p1 AND NOT p2)
	bic p1.b, p0/z, p1.b, p2.b // Bitwise Clear p1 where p2 is true (zeroing)
.L_q_not_o_easy:

	// Filter 2: Remove cases where P = Q. This happens if x1=x2 and y1=y2.
	cmp w20, w22               // Check scalar x1 == x2
	b.ne .L_p_not_q_easy       // If x1 != x2, P cannot be Q, skip this filter step
	// If x1 == x2: Check vector y1 == y2
	cmpeq p2.s, p0/z, z0.s, z6.s // p2 = predicate where y2 == y1 (using z6=y1, zeroing)
	// Remove lanes from p1 where P=Q condition is met (p1 = p1 AND NOT p2)
	bic p1.b, p0/z, p1.b, p2.b // Bitwise Clear p1 where p2 is true (zeroing)
.L_p_not_q_easy:

	// Count the number of true elements in the final predicate p1 under the loop predicate p0
	// This gives the number of valid right triangles found in this SVE iteration
	cntp x25, p0, p1.s          // x25 = count of true lanes in p1 governed by p0
	add	x19, x19, x25          // Add the count for this iteration to the total count x19

	// Increment the y2 index for the next SVE iteration
	add	x23, x23, x28          // y2_idx += number of S elements per vector
	b	.L_y2_loop_sve         // Branch back to the start of the SVE loop

.L_y2_loop_sve_end:              // End of the SVE loop over y2
	// --- End of vectorized y2 loop ---

	// Increment scalar x2 and loop back
	add	w22, w22, #1           // x2++
	cmp	w22, #51               // Compare x2 with 51 (loop condition x2 < 51)
	b.ne	.L_x2_loop         // Branch if x2 != 51 (continue x2 loop)

.L_skip_y1_inc:                  // Label jumped to if P=O (x1=0, y1=0)
	// Increment scalar y1 and loop back
	add	w21, w21, #1           // y1++
	cmp	w21, #51               // Compare y1 with 51 (loop condition y1 < 51)
	b.ne	.L_y1_loop         // Branch if y1 != 51 (continue y1 loop)

	// Increment scalar x1 and loop back
	add	w20, w20, #1           // x1++
	cmp	w20, #51               // Compare x1 with 51 (loop condition x1 < 51)
	b.ne	.L_x1_loop         // Branch if x1 != 51 (continue x1 loop)

	// All loops have finished.
	// The count in x19 is double the actual number of triangles because
	// pairs of points (P, Q) and (Q, P) are counted separately but represent
	// the same triangle O P Q. Divide the total count by 2.
	lsr x19, x19, #1           // Logical Shift Right x19 by 1 (x19 = x19 / 2)

	// Print the final result using printf
	adrp	x0, .L.str         // Load page address of the format string
	add	x0, x0, :lo12:.L.str // Add offset to get the exact address of .L.str
	mov	x1, x19               // Move the final count (x19) to x1 (second argument for printf)
	bl	printf                // Call the printf function

	// Restore saved registers and return 0 from main
	mov	w0, #0                 // Set return value w0 to 0
	ldp	x29, x30, [sp, #72]    // Restore FP (x29), LR (x30)
	ldp	x27, x28, [sp, #64]    // Restore x27, x28
	ldp	x25, x26, [sp, #48]    // Restore x25, x26
	ldp	x23, x24, [sp, #32]    // Restore x23, x24
	ldp	x21, x22, [sp, #16]    // Restore x21, x22
	ldp	x19, x20, [sp], #80    // Restore x19, x20 and deallocate stack (SP += 80)
	.cfi_def_cfa_offset 0      // Restore Canonical Frame Address offset to 0
	ret                        // Return to the caller
.Lfunc_end1:
	.size	main, .Lfunc_end1-main // Define the size of the main function
	.cfi_endproc                   // End of Call Frame Information for main

	// Read-only data section for the format string used by printf
	.type	.L.str,@object
	.section	.rodata.str1.1,"aMS",@progbits,1 // Section attributes: allocatable, MergeableStrings, String, progbits, align=1
.L.str:
	.asciz	"%ld"           // Format string: long decimal integer (%ld) WITHOUT newline
	.size	.L.str, 4          // Size of the string literal (including null terminator) - Updated size

	.ident	"Translated to SVE by AI - Fixed errors based on trace - No newline" // Optional identifier string in the object file
	.section	".note.GNU-stack","",@progbits             // Add a note indicating the stack is not executable
	.addrsig                   // Emit address significance table for linker relaxation
