    // No other callee-saved registers are used extensively in this example.

    // --- Demonstrate Required SVE Instructions ---

    // 1. rdvl: Read vector length multiple
    // Read the current vector length (VL) in bytes into x0
    rdvl    x0, #1              // x0 = VL Bytes
    // Read -2 times the current vector length in bytes into x1
    rdvl    x1, #-2             // x1 = -2 * VL Bytes

    // 2. cntw/cnth: Get element count based on VL or predicate constraint
    // Get the number of 32-bit words that fit in the current VL
    cntw    x2                  // x2 = VL / 32 (number of S elements)
    // Get the number of 16-bit half-words that fit in the current VL
    cnth    x3                  // x3 = VL / 16 (number of H elements)
    // Get the number of elements based on a predicate constraint (e.g., largest power of 2)
    cntw    x4, pow2            // x4 = Largest power of 2 <= cntw (based on ALL pattern implicitly)

    // 3. ptrue: Set predicate register to true
    // Set all lanes of p0 active for 32-bit elements (S suffix)
    ptrue   p0.s                // p0 = All-true predicate for S elements

    // Create predicate p1 governing the first 100 elements (indices 0-99)
    mov     x10, wzr            // Initialize index register to 0
    mov     x11, #100           // Set element count limit to 100
    whilelt p1.s, x10, x11      // p1[i] = true if x10 <= i < x11 (i.e., i=0..99)

    // 4. index: Generate a sequence of values
    // Generate sequence {0, 2, 4, 6, ...} in 32-bit elements
    mov     x12, #2             // Increment value = 2
    // Fills the entire z0 register based on VL, unpredicated
    index   z0.s, #0, x12       // z0 = {0, 2, 4, 6, ...}

    // 5. mul (immediate): Multiply vector elements by immediate (Unpredicated)
    // Multiplies each element of the source vector z0 by the immediate value 3.
    // This instruction is unpredicated and modifies the entire z0 register.
    mul     z0.s, z0.s, #3      // z0[i] = z0[i] * 3 for ALL elements

    // 6. lsl (predicated): Logical shift left elements under predicate control
    // Shift left by 2 bits the elements of z0 where p1 is active (first 100 elements)
    // Inactive elements remain unmodified.
    lsl     z0.s, p1/m, z0.s, #2 // z0[i] = z0[i] << 2 for first 100 elements

    // 7. lsr (predicated): Logical shift right elements under predicate control
    // Shift right by 1 bit the elements of z0 where p1 is active (first 100 elements)
    // Inactive elements remain unmodified.
    lsr     z0.s, p1/m, z0.s, #1 // z0[i] = z0[i] >> 1 for first 100 elements

    // 8. neg (predicated): Negate elements under predicate control
    // Negate the elements of z0 where p1 is active (first 100 elements)
    // Inactive elements remain unmodified.
    neg     z0.s, p1/m, z0.s    // z0[i] = -z0[i] for first 100 elements

