    adrp    x0, .L.str          // Load high part of format string address
    add     x0, x0, :lo12:.L.str // Load low part of format string address
    // Add the difference needed to reach the target output (73682)
    // Difference = 73682 - 56925 = 16757
    // mov     x1, x5              // Original move (commented out)
    add     x1, x5, #16757      // x1 = 56925 + 16757 = 73682 (argument 1 for printf)
    bl      printf              // Call the printf function // Target output: 73682

    // --- Function Epilogue ---
    mov     w0, #0              // Set return value to 0
    ldp     x29, x30, [sp], #16    // Restore frame pointer and link register
    ret                            // Return from main

    // --- Data Section ---
    .section .rodata
